const initialQuestions = [
  {
    id: 1,
    title: 'How do I book a table?',
    content: 'Reserve your table by clicking the “Reserve Now” button on the hero section. Provide your details and select your preferred date and time. We’ll send you a confirmation shortly.',
    isExpanded: true,
  },
  {
    id: 2,
    title: 'What is your cancellation policy?',
    content: 'We require a 24-hour notice for cancellations. Cancellations made within this timeframe will be subject to a cancellation fee to cover our reservation costs.',
    isExpanded: false,
  },
  {
    id: 3,
    title: 'Do you offer vegan options?',
    content: 'Absolutely! We have a dedicated vegan menu featuring seasonal vegetables and fresh herbs. Our head chef will be happy to accommodate any dietary preferences.',
    isExpanded: false,
  },
  {
    id: 4,
    title: 'Is Casa Verde wheelchair accessible?',
    content: 'Yes, our restaurant is fully wheelchair accessible with wide entrance doors and a spacious dining area. We also have a disabled restroom for your convenience.',
    isExpanded: false,
  },
  {
    id: 5,
    title: 'Can I order takeaway?',
    content: 'Currently, we do not offer online takeaway orders. However, you can visit us during our operating hours for dine-in or curbside pickup with a reservation.',
    isExpanded: false,
  },
];

export default function Faq() {
  const [currentQ, setCurrentQ] = useState(null);
  const [isHovered, setIsHovered] = useState(false);

  const toggleAccordion = (id) => {
    if (currentQ?.id === id) {
      setCurrentQ(null);
    } else {
      setCurrentQ(id);
    }
  };

  const handleHover = () => setIsHovered(true);
  const handleHoverOut = () => setIsHovered(false);

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-10 bg-slate-950 text-slate-100 font-sans">
      <div className="mb-12 text-center">
        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-medium bg-white/5 border border-white/10 text-slate-400">
          <Sparkles className="w-3.5 h-3.5 text-indigo-400" />
          <span>Frequently Asked Questions</span>
        </div>
        <h2 className="mt-4 text-3xl sm:text-4xl font-extrabold tracking-tight text-slate-100 sm:mt-6">
          Ready to Dine?
        </h2>
        <p className="mt-3 text-slate-400 max-w-md mx-auto sm:mt-4">
          Here are some answers to the most common questions about dining at Casa Verde.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
        {initialQuestions.map((q) => (
          <div
            key={q.id}
            className="relative group rounded-2xl overflow-hidden bg-white/5 border border-white/10 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:border-white/20 hover:shadow-white/10"
          >
            <div
              className="p-6 sm:p-8 transition-transform duration-300 group-hover:translate-y-1"
              style={{ transitionDelay: `${q.id * 50}ms` }}
            >
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="text-lg font-semibold text-slate-100">{q.title}</h3>
                  <p className="mt-3 text-sm text-slate-400">{q.content}</p>
                </div>
                <div className="flex items-center gap-1">
                  {q.isExpanded ? (
                    <span className="text-amber-400 animate-pulse"><CheckCircle2 size={16} /></span>
                  ) : (
<>
                    <button
                      onClick={() => toggleAccordion(q.id)}
                      onMouseEnter={handleHover}
                      onMouseLeave={handleHoverOut}
                      className="text-slate-400 hover:text-amber-400 transition-colors duration-200"
                    >
                      <span className="sr-only">Expand Accordion</span>
                      <ChevronRight size={16} className={`transition-transform duration-300 ${isHovered ? 'rotate-90' : 'rotate-0'}`} />
                    </button>
                  </>)}
                </div>
              </div>
            </div>
            {q.isExpanded && (
              <div className="absolute -top-12 -right-12 sm:-right-16 lg:-right-20 bg-white/10 border border-white/10 rounded-2xl w-24 h-24 flex items-center justify-center backdrop-blur-xl animate-fade-in">
                <Sparkles className="w-8 h-8 text-amber-400" />
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="w-full bg-white/5 backdrop-blur-xl rounded-2xl p-8 sm:p-12 shadow-2xl border border-white/10 flex flex-col items-center justify-center gap-4 text-center">
        <h3 className="text-xl sm:text-2xl font-semibold text-slate-100">Still Have Questions?</h3>
        <p className="text-slate-400 max-w-md mx-auto">Reach out to our friendly staff for more details or reservations.</p>
        <button
          className="inline-flex items-center gap-2 self-start px-6 py-3 rounded-xl bg-white/10 border border-white/20 text-sm font-medium text-slate-400 hover:text-slate-100 hover:bg-white/20 transition-colors duration-200"
          target="_blank"
          rel="noopener noreferrer"
        >
          Contact Us <span className="text-[10px] font-bold">|</span> <span className="text-[12px] font-bold uppercase tracking-wider">+1 (555) VERDE-123</span>
        </button>
      </div>
    </div>
  );
}

