const initialSearchTerm = '';

export default function Menu() {
  const [searchTerm, setSearchTerm] = useState(initialSearchTerm);
  const [filterBy, setFilterBy] = useState('All');
  const [favoritedDishes, setFavoritedDishes] = useState(new Set());
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchActive, setIsSearchActive] = useState(false);

  const filteredDishes = signatureDishes.filter((dish) => {
    const matchesSearch = dish.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterBy === 'All' || dish.name.startsWith(filterBy);
    return matchesSearch && matchesFilter;
  });

  const toggleFavorite = (id) => {
    setIsLoading(true);
    setTimeout(() => {
      const newSet = new Set(favoritedDishes);
      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }
      setFavoritedDishes(newSet);
      setIsLoading(false);
    }, 500);
  };

  return (
    <div className="w-full bg-slate-950 text-slate-100 font-sans antialiased min-h-screen">
      <div className="relative flex flex-col items-center justify-center min-h-[80vh] pb-16 sm:pb-24 lg:pb-32">
