        <div className="relative z-10 w-full max-w-3xl text-center">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/5 border border-white/10 text-xs font-medium text-slate-400 uppercase tracking-wider">
            <MapPin className="w-3.5 h-3.5 text-indigo-400" />
            <span>Casa Verde</span>
          </div>
          <h1 className="mt-4 text-4xl font-extrabold tracking-tight text-white sm:text-5xl lg:text-6xl">
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-purple-600">Signature Dishes</span>
          </h1>
          <p className="mt-2 text-slate-400 max-w-md text-sm sm:text-base">
            {isSearchActive
              ? 'Filtering results for your taste palette...'
              : 'Experience the flavors of Italy with our handcrafted dishes.'}
          </p>
          {isSearchActive && (
            <div className="w-full max-w-md mt-8">
              <div className="relative">
                <div className="absolute inset-y-1.5 left-6 flex items-center pointer-events-none">
                  <Search className="w-4 h-4 text-slate-400" />
                </div>
                <input
                  type="search"
                  placeholder="Search for a dish..."
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setIsSearchActive(true);
                  }}
                  className="block w-full bg-white/5 border border-white/10 rounded-md py-2 pl-12 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 placeholder:text-slate-500 sm:text-base"
                />
              </div>
            </div>
          )}
          {!isSearchActive && (
            <div className="mt-8">
              <div className="flex flex-wrap -m-2">
                {['All', 'Appetizers', 'Main Courses', 'Desserts'].map((label, idx) => (
                  <div
                    key={idx}
                    className="p-2 text-sm font-medium rounded-xl bg-white/5 hover:bg-white/10 transition-colors duration-200 cursor-pointer"
                    onClick={() => setFilterBy(label)}
                    style={{
                      backgroundColor: filterBy === label ? 'rgba(255, 255, 255, 0.1)' : 'transparent',
                      borderColor: filterBy === label ? 'rgba(255, 255, 255, 0.2)' : 'transparent'
                    }}
                  >
                    {label}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="w-full max-w-4xl mx-auto px-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {isLoading ? (
            <div className="col-span-3 sm:col-span-2 lg:col-span-1 animate-pulse rounded-xl bg-white/5 border border-white/10 shadow-lg p-6 h-64 sm:h-80 max-w-sm">
              <div className="h-12 w-2/3 bg-white/10 rounded mb-4" />
              <div className="h-6 w-1/3 bg-white/10 rounded my-2" />
              <div className="h-6 w-2/3 bg-white/10 rounded" />
            </div>
          ) : (
<>
            filteredDishes.map((dish) => {
              const isFavorited = favoritedDishes.has(dish.id);
              const activeFilter = filterBy === 'All' || dish.name.startsWith(filterBy);
              if (!activeFilter) return null;
              return (
                <div
                  key={dish.id}
                  className="group relative overflow-hidden rounded-2xl border border-white/10 bg-white/5 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:border-white/20 hover:bg-white/10"
                >
                  <div className="absolute -inset-0.5 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
