                      src={dish.imageUrl}
                      alt={dish.name}
                      className="absolute inset-0 h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.02]"
                    />
                  </div>
                  <div className="pt-6">
                    <div className="mb-2 flex items-center gap-2">
                      {isFavorited ? (
                        <Heart className="w-5 h-5 text-amber-400 animate-pulse" />
                      ) : (
                        <Sparkles className="w-5 h-5 text-slate-500" />
                      )}
                      <span className="text-sm font-medium text-slate-300">{dish.name}</span>
                    </div>
                    <p className="text-sm text-slate-400">{dish.description}</p>
                    <div className="mt-4 flex items-center justify-between">
                      <span className="text-xl font-bold text-slate-300">{dish.price}</span>
                      <button
                        type="button"
                        onClick={() => toggleFavorite(dish.id)}
                        className="inline-flex items-center gap-1.5 rounded-full bg-white/5 px-3 py-1.5 text-sm font-medium text-slate-400 transition-colors hover:bg-white/10 active:scale-95"
                      >
                        {isFavorited ? (
                          <Sparkle className="w-3.5 h-3.5 text-amber-400" />
                        ) : (
                          <Heart className="w-3.5 h-3.5 text-slate-500" />
                        )}
                        {isFavorited ? 'Unfavorited' : 'Add to Favorites'}
                      </button>
                    </div>
                  </div>
                </div>
              );
            })
          </>)}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
