    { id: '2030', time: '8:30 PM', availability: 'booked' },
    { id: '2100', time: '9:00 PM', availability: 'booked' },
    { id: '2130', time: '9:30 PM', availability: 'available' },
  ]);

  const handleTimeChange = (timeId) => {
    const newSlots = timeSlots.map(slot => {
      if (slot.id === timeId) {
        return { ...slot, availability: 'booked' };
      }
      return slot;
    });
    setTimeSlots(newSlots);
  };

  const [loadingMaps, setLoadingMaps] = useState(false);

  const handleMapToggle = () => {
    setLoadingMaps(true);
    setTimeout(() => setLoadingMaps(false), 1000);
  };

  const [activeStep, setActiveStep] = useState('1');

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans antialiased">
