            </div>
          </div>

          {/* Step 1: Details Form */}
          {activeStep === '1' && (
            <div className="space-y-6 sm:space-y-8">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6">
                <div className="space-y-2">
                  <label htmlFor="name" className="block text-sm font-medium text-slate-300">Full Name</label>
                  <input 
                    id="name" 
                    value={details.name} 
                    onChange={(e) => setDetails({ ...details, name: e.target.value })}
                    type="text" 
                    placeholder="Davide Rossi" 
                    className="w-full bg-white/5 border border-white/10 rounded-lg py-2 px-3 shadow-sm text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300" 
                  />
                </div>
                <div className="space-y-2">
                  <label htmlFor="guests" className="block text-sm font-medium text-slate-300">Guests</label>
                  <div className="relative">
                    <select
                      id="guests"
                      value={details.guests}
                      onChange={(e) => setDetails({ ...details, guests: parseInt(e.target.value) })}
                      className="w-full bg-white/5 border border-white/10 rounded-lg py-2 px-3 shadow-sm text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                    >
                      <option value="2">2</option>
                      <option value="4">4</option>
                      <option value="6">6</option>
                      <option value="8">8</option>
                    </select>
                    <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none">
                      <span className="text-slate-400">pax</span>
                    </div>
                  </div>
                </div>
                <div className="space-y-2">
                  <label htmlFor="date" className="block text-sm font-medium text-slate-300">Date</label>
                  <input 
                    id="date" 
                    type="date" 
                    min="2023-10-01" 
                    value={details.date} 
                    onChange={(e) => setDetails({ ...details, date: e.target.value })}
                    className="w-full bg-white/5 border border-white/10 rounded-lg py-2 px-3 shadow-sm text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300" 
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                <div className="space-y-2">
                  <label htmlFor="time" className="block text-sm font-medium text-slate-300">Time</label>
                  <select
                    id="time"
                    value={details.time}
                    onChange={(e) => setDetails({ ...details, time: e.target.value })}
                    className="w-full bg-white/5 border border-white/10 rounded-lg py-2 px-3 shadow-sm text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300"
                  >
                    {timeSlots.map(slot => 
                      <option key={slot.id} value={slot.id}>
                        {slot.time} {slot.availability === 'booked' && <span className="text-rose-500">[Full]</span>}
                      </option>
                    )}
                  </select>
                </div>
                <div className="space-y-2">
                  <label htmlFor="phone" className="block text-sm font-medium text-slate-300">Phone</label>
                  <input 
                    id="phone" 
                    value={details.phone} 
                    onChange={(e) => setDetails({ ...details, phone: e.target.value })}
                    type="tel" 
                    placeholder="+39 345 678 9012" 
                    className="w-full bg-white/5 border border-white/10 rounded-lg py-2 px-3 shadow-sm text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300" 
                  />
                </div>
                <div className="space-y-2">
                  <label htmlFor="email" className="block text-sm font-medium text-slate-300">Email</label>
                  <input 
                    id="email" 
                    value={details.email} 
                    onChange={(e) => setDetails({ ...details, email: e.target.value })}
                    type="email" 
                    placeholder="davide@verderistori.it" 
                    className="w-full bg-white/5 border border-white/10 rounded-lg py-2 px-3 shadow-sm text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500/30 transition-all duration-300" 
                  />
                </div>
              </div>
              <div className="flex justify-end mt-8">
                <button 
                  onClick={() => setActiveStep('2')}
                  disabled={isLoading}
                  className="inline-flex items-center justify-center gap-2 px-4 py-2 text-sm font-medium rounded-xl bg-indigo-600/10 border border-indigo-600/20 text-indigo-300 hover:bg-indigo-600/20 active:scale-95 transition-all duration-200"
                >
                  {isLoading ? <span className="animate-spin text-slate-400"><Clock size={14} /></span> : <Sparkles className="w-4 h-4" />} Complete Reservation
                </button>
              </div>
            </div>
          )}

          {/* Step 2: Confirmation */}
          {activeStep === '2' && (
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 p-6 sm:p-8 bg-white/5 rounded-2xl border border-white/10 shadow-lg shadow-indigo-900/30">
              <div>
                <h2 className="text-xl font-semibold text-slate-100 tracking-tight">Reservation Confirmed!</h2>
                <p className="text-slate-400 mt-2 max-w-md text-sm sm:text-base">Thank you, {details.name}! Your table is reserved.</p>
                <div className="mt-6">
                  <span className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-emerald-600/20 border border-emerald-600/30 text-emerald-400 text-sm font-medium">
                    <CheckCircle2 className="w-4 h-4" /> Ready to dine.
                  </span>
                </div>
              </div>
              <div className="flex items-center gap-4 mt-8 sm:mt-0">
                <a 
                  href={`https://www.google.com/maps?q=${encodeURIComponent('Casa Verde, Via dei Giardini 1, 20121 Milano')}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-slate-300 text-sm font-medium hover:bg-white/10 transition-colors duration-300"
                >
                  <MapPin className="w-4 h-4" /> View on map
                </a>
                <button 
                  onClick={() => setActiveStep('1')}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-slate-300 text-sm font-medium hover:bg-white/10 transition-colors duration-300"
                >
                  <ArrowRight className="w-4 h-4" /> Edit Details
                </button>
              </div>
            </div>
          )}

          {/* Decorative Gradient Decorative Arrow */}
          <div className="absolute bottom-1/4 left-1/4 w-32 h-32 bg-indigo-600/20 rounded-bl-2xl bg-gradient-to-t from-transparent via-indigo-500/10 to-indigo-400/10 pointer-events-none" />
        </div>
      </div>

      {/* Decorative Bottom Gradient */}
      <div className="absolute inset-0 w-full h-48 bg-gradient-to-t from-indigo-600 via-purple-600 to-pink-600 opacity-10" />
    </div>
  );
}
